const ROLES: UserRole[] = [
  'seller_premium', 'seller_premium', 'seller_free', 'buyer_premium', 
  'buyer_free', 'buyer_free', 'procurement', 'moderator'
];

/**
 * Generates 100 realistic users (Core 6 users + 94 algorithmic realistic profiles).
 * 100% Universal - works seamlessly in browser client bundles and Node.js backend.
 */
export function generate100Users(): User[] {
  const users: User[] = [...CORE_USERS];

  for (let i = 1; i <= 94; i++) {
    const fn = FIRST_NAMES[(i * 3) % FIRST_NAMES.length];
    const ln = LAST_NAMES[(i * 7) % LAST_NAMES.length];
    const name = `${fn} ${ln}`;
    const username = `${fn.toLowerCase()}_${ln.toLowerCase()}_${i}`;
    const role = ROLES[i % ROLES.length];
    const isPremium = role === 'seller_premium' || role === 'buyer_premium' || role === 'admin' || role === 'procurement';
    const isVerified = isPremium || (i % 3 === 0);
    const company = (i % 2 === 0 || isPremium) ? COMPANIES[i % COMPANIES.length] : undefined;
    const location = CITIES[i % CITIES.length];
    const avatar = AVATAR_URLS[i % AVATAR_URLS.length];

    const followers = Math.floor(50 + (i * 97) % 8500);
    const following = Math.floor(20 + (i * 43) % 850);
    const totalSales = role.includes('seller') ? Math.floor(10 + (i * 29) % 1800) : 0;
    const rating = Number((4.5 + ((i % 5) * 0.1)).toFixed(1));
    const reviewsCount = Math.floor(totalSales * 0.2) + 5;

    users.push({
      id: `usr_gen_${i}`,
      name,
      username,
      email: `${fn.toLowerCase()}.${ln.toLowerCase()}@${company ? 'company.com' : 'example.com'}`,
      avatar,
      coverImage: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&auto=format&fit=crop&q=80',
      role,
      companyName: company,
      bio: company 
        ? `Official B2B storefront & procurement channel for ${company}. Verified verified partner.`
        : `Active buyer & commerce partner on BizSocial. Specializing in ${location.split(',')[0]} local goods.`,
      isVerified,
      verificationBadgeType: isVerified ? (isPremium ? 'b2b_verified' : 'merchant_verified') : undefined,
      subscriptionStatus: isPremium ? 'premium' : 'free',
      location,
      followersCount: followers,
      followingCount: following,
      rating: rating > 5.0 ? 5.0 : rating,
      reviewsCount,
      totalSales,
      createdAt: `2024-${String((i % 12) + 1).padStart(2, '0')}-15`
    });
  }

  return users;
}

// Pre-computed in-memory 100 users for instantaneous zero-latency access in browser and server
export const GENERATED_100_USERS: User[] = generate100Users();

/**
 * Returns the 100 generated users (Universal helper).
 */
export function getOrSeed100Users(): User[] {
  return GENERATED_100_USERS;
}
